CREATE TABLE card_imports (
 character_id INTEGER PRIMARY KEY, baseline_json TEXT NOT NULL
)

CREATE TABLE item_use_posts (
 use_id INTEGER PRIMARY KEY REFERENCES item_uses(id), posted_at REAL NOT NULL
)

CREATE TABLE model_profiles (
 name TEXT PRIMARY KEY, data_json TEXT NOT NULL, revision INTEGER NOT NULL, updated_at REAL NOT NULL
)

CREATE TABLE scene_resets (
 channel_id INTEGER PRIMARY KEY, reset_at REAL NOT NULL
)

CREATE TABLE shop_purchases (
 ledger_id INTEGER PRIMARY KEY REFERENCES currency_ledger(id), guild_id INTEGER NOT NULL, user_id INTEGER NOT NULL, item_key TEXT NOT NULL
)

CREATE TABLE thread_casts (
 thread_id INTEGER PRIMARY KEY, cast TEXT NOT NULL, guild_id INTEGER, parent_id INTEGER
)

CREATE TABLE trace (
 response_id INTEGER PRIMARY KEY, details_json TEXT NOT NULL
)

CREATE TRIGGER lore_insert_identity AFTER INSERT ON lore WHEN new.entry_key='' BEGIN
            UPDATE lore SET entry_key='entry:'||lower(hex(randomblob(16))),revision=(random() & 4611686018427387903)+1 WHERE id=new.id;
        END

